  "pa.how.steps": [{"t":"Minta tautan Anda","b":"Isi formulir di bawah ini. Anda akan mendapatkan tautan pribadi yang berisi kode Anda sendiri.","d":"Kamu"},{"t":"Bagikan kepada audiens Anda","b":"Siapa pun yang meminta penawaran harga melalui tautan Anda akan secara otomatis mendapatkan diskon 10% dari harga tersebut.","d":"Kamu"},{"t":"Klien membayar tagihan tersebut","b":"Segera setelah tagihan dibayarkan melalui portal klien, komisi 5% Anda akan dikunci. Bukan berdasarkan permintaan — melainkan berdasarkan pembayaran.","d":"Kami"},{"t":"Dibayarkan setiap bulan","b":"Anda dapat memantau setiap klik, permintaan, dan komisi melalui dasbor Anda sendiri. Penghasilan yang diperoleh dalam satu bulan akan kami bayarkan pada bulan berikutnya.","d":"Kami"}],
